) -&gt; list[list[dict]]:
    instruction = self._resolve_instruction(memory)

    out: list[list[dict]] = []
    for chat in messages:
        chat = list(chat)
        if chat and chat[0].get("role") == "system":
            existing = chat[0].get("content", "")
            if self.mode == "prepend":
