Source code in <code>steerability/algorithms/input_control/cpo/utils/embeddings.py</code> <pre><code>@torch.no_grad()
def encode_batch(self, texts: Sequence[str]) -&gt; np.ndarray:
    if not texts:
        return np.zeros((0, self.model.config.hidden_size), dtype=np.float32)
    inputs = self.tokenizer(
        list(texts), return_tensors="pt", truncation=True, padding=True
    ).to(self.device)
    outputs = self.model(**inputs)
    hidden = outputs.last_hidden_state  # [B, T, H]
    mask = inputs["attention_mask"].unsqueeze(-1).to(hidden.dtype)
    pooled = (hidden * mask).sum(dim=1) / mask.sum(dim=1).clamp(min=1.0)
    return pooled.cpu().numpy()
</code></pre>

